SELECT result_date, result_count FROM ( SELECT DECODE(result_date, '00', '24', result_date) AS result_date, SUM(result_count) AS result_count FROM ( SELECT TO_CHAR(TO_DATE('00', 'HH24') + LEVEL / 24, 'HH24') AS result_date, 0 AS result_count FROM DUAL CONNECT BY LEVEL <= 24 UNION ALL SELECT TO_CHAR(access_date, 'HH24') AS result_date, COUNT(*) AS result_count FROM ARCHIVE_STATISTICS
AND homepage_id = #{homepage_id}
AND TO_CHAR(access_date, 'yyyy-MM-dd') = #{search_date}
GROUP BY TO_CHAR(access_date, 'HH24') ) GROUP BY result_date ) ORDER BY result_date

SELECT
	COUNT(*)
FROM
	ARCHIVE_STATISTICS


AND	homepage_id = #{homepage_id}


	
	AND	TO_CHAR(access_date, 'yyyy-MM-dd') = #{search_date}
	
	
	AND	TO_CHAR(access_date, 'yyyy-MM') = #{search_date}
	
	
	AND	TO_CHAR(access_date, 'yyyy') = #{year}
